+  } catch (e: any) {
+    console.error(chalk.red(`Refusing ${verb}: cannot reach ${url}/healthz — ${e?.message ?? e}`));
+    console.error(chalk.gray('  Nothing was written. A hub that does not answer /healthz is not a hub.'));
+  }
+  return false;
