      return { status: 200, data: { ok: true, rewritten: 4 } };
    });
    fs.chmodSync(AGENFK_DIR, 0o500);
    try {
      await expect(run(makeProgram(), repointArgs(['--carry-over', '--yes', '--no-restart']))).rejects.toThrow('exit 1');
